import{_ as o,c as e,o as s,ag as r}from"./chunks/framework.Cycwnjj0.js";const a="/assets/add-classic-editor-block-in-a-post.CmrYxuV_.webp",n="/assets/add-media-option-from-the-classic-editor.dP_S4wwm.webp",i="/assets/grid-template-option.EkKxIaSX.webp",d="/assets/preview-of-grid-templated-product.CnZfd8Rb.webp",b=JSON.parse('{"title":"Grid Template","description":"","frontmatter":{},"headers":[],"relativePath":"guide/available-products-templates/grid-template.md","filePath":"guide/available-products-templates/grid-template.md"}'),l={name:"guide/available-products-templates/grid-template.md"};function p(g,t,c,u,h,m){return s(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="grid-template" tabindex="-1">Grid Template <a class="header-anchor" href="#grid-template" aria-label="Permalink to &quot;Grid Template&quot;">​</a></h1><p>AzonPress offers an advanced feature to <strong>display Amazon products</strong> using the <strong>WordPress Classic Editor</strong>. This article guides you through using the <strong>Grid Template</strong> of <strong>AzonPress</strong> in the <strong>Classic Editor</strong> of <strong>WordPress</strong>.</p><h2 id="grid-template-of-azonpress" tabindex="-1">Grid Template of AzonPress <a class="header-anchor" href="#grid-template-of-azonpress" aria-label="Permalink to &quot;Grid Template of AzonPress&quot;">​</a></h2><p>You can use the <strong>Grid Template</strong> to symmetrically exhibit your products so that customers can easily conceive the ins and outs of a product.</p><p>To learn how to use Grid Template, follow the steps with the screenshots below –</p><p>First, add the <strong>Classic Editor</strong> block on your desired <strong>Page/Post</strong> (e.g., I have added the classic editor to a new post).</p><p>Now, to add the <strong>Classic Editor</strong>, click the Gutenberg editor&#39;s <strong>Plus (+) icon</strong>.</p><p><img src="'+a+'" alt="Add Classic editor block in a post"></p><p>Next, click the <strong>Add Media</strong> option from the <strong>classic editor</strong> bar, and a pop-up window appears with a couple of options.</p><p><img src="'+n+'" alt="Add media option from the classic editor"></p><p>Now, press <strong>AzonPress</strong> from the left sidebar and you will get <strong>Product Templates</strong> tabs with various <strong>settings options</strong> for <strong>showcasing</strong> your <strong>Amazon products.</strong></p><ul><li>Here, you will get the <strong>Grid</strong> template under the <strong>Select Layout</strong> option, <strong>enable</strong> the <strong>checkbox</strong> to use this.</li><li>Select how many columns you want for showcasing your products by clicking the <strong>Arrow Icon</strong> under <strong>Select number of column</strong> dropdown.</li><li>To learn about how to use all the other settings options under Product Templates, read this <a href="/guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.html">Documentation</a>.</li><li>Once you are done, click the <strong>Insert Shortcode</strong> button and the shortcode will be automatically embedded in your post. Then, <strong>publish</strong> it and your Amazon Products will appear on your site under that post.</li><li>If you want to <strong>showcase the same products</strong> in <strong>another post/s</strong>, you can also do it simply by <strong>copying</strong> the <strong>Shortcode</strong> visible <strong>right before</strong> the <strong>Insert Shortcode</strong> button and <strong>pasting</strong> it into the desired post/s.</li></ul><p><img src="'+i+'" alt="Grid template option"></p><p>Here, is the preview of the post where the selected Amazon Products are displayed as a Grid template.</p><p><img src="'+d+'" alt="Preview of Grid Template Product"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',17)])])}const w=o(l,[["render",p]]);export{b as __pageData,w as default};
